add_action('init', function () {
  if (get_option('x_meital_yoast_v1')) { return; }
  $m = json_decode(base64_decode(''), true);
  if (!is_array($m)) { return; }
  foreach ($m as $id => $f) { foreach ($f as $k => $v) { update_post_meta((int) $id, $k, $v); } }
  update_option('x_meital_yoast_v1', 1, false);
});
